const input = $input.first().json;
const payload = input.body ?? input;
const lead = payload.lead;
const requiredTextFields = ['_id', 'name', 'email', 'phone', 'company', 'source', 'enquiry'];
const allowedStatuses = ['New', 'Contacted', 'Qualified', 'Converted', 'Lost'];

if (payload.event !== 'lead.created' || !lead || typeof lead !== 'object' || Array.isArray(lead)) {
  throw new Error('Expected a lead.created event with a lead object.');
}

for (const field of requiredTextFields) {
  if (typeof lead[field] !== 'string' || lead[field].trim() === '') {
    throw new Error(`Lead field "${field}" is required.`);
  }
}

if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.email.trim())) {
  throw new Error('Lead email is invalid.');
}

if (!allowedStatuses.includes(lead.status)) {
  throw new Error('Lead status is invalid.');
}

return [{
  json: {
    event: payload.event,
    receivedAt: new Date().toISOString(),
    lead: {
      _id: lead._id,
      name: lead.name.trim(),
      email: lead.email.trim().toLowerCase(),
      phone: lead.phone.trim(),
      company: lead.company.trim(),
      source: lead.source.trim(),
      enquiry: lead.enquiry.trim(),
      status: lead.status,
      createdAt: lead.createdAt ?? null,
      updatedAt: lead.updatedAt ?? null
    }
  }
}];
